<template><section v-if="core.busy" class="scr-progress" aria-live="polite"><div><strong>{{ core.progress?.label }}</strong><span>{{ t('status.progress', { percent }) }}</span></div><div class="scr-progress-track" role="progressbar" :aria-label="t('a11y.progress')" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="percent"><i :style="{ width: `${percent}%` }"></i></div><button type="button" @click="$emit('cancel')">{{ t('status.cancelSafe') }}</button></section></template>
<script setup>import { computed } from "vue"; import { useStores } from "../../stores/index.js"; defineEmits(["cancel"]); const stores = useStores(); const core = stores.core.state; const { t } = stores.i18n; const percent = computed(() => Math.round(Number(core.progress?.value || 0) * 100))</script>
